import { NextResponse } from "next/server";
import { prisma } from "@tiips/db";

export async function GET() {
    try {
        // Find all paid invoices
        const paidInvoices = await prisma.invoice.findMany({
            where: { status: "PAID" },
            include: { order: true }
        });

        const updates = [];

        for (const invoice of paidInvoices) {
            if (invoice.order && (invoice.order.status !== "PAID" || invoice.order.validationStatus !== "VALID")) {
                updates.push(prisma.order.update({
                    where: { id: invoice.orderId },
                    data: {
                        status: "PAID",
                        validationStatus: "VALID"
                    }
                }));
            }
        }

        await prisma.$transaction(updates);

        return NextResponse.json({
            success: true,
            updatedCount: updates.length,
            message: `Updated ${updates.length} orders to PAID status.`
        });
    } catch (error) {
        console.error("Fix script error:", error);
        return NextResponse.json({ error: "Failed to fix data" }, { status: 500 });
    }
}
